-- Criar acordo de teste
INSERT INTO acordos (devedorId, condominioId, totalAmount, agreedAmount, installments, firstPaymentDate, paymentFrequency, status, notes, valorPago)
VALUES (1, 1, 500000, 450000, 3, '2026-03-01', 'mensal', 'ativo', 'Acordo de teste para validar dar baixa', 0);

SET @acordo_id = LAST_INSERT_ID();

-- Criar parcelas do acordo
INSERT INTO parcelasAcordo (acordoId, installmentNumber, amount, dueDate, status)
VALUES 
  (@acordo_id, 1, 150000, '2026-03-01', 'pendente'),
  (@acordo_id, 2, 150000, '2026-04-01', 'pendente'),
  (@acordo_id, 3, 150000, '2026-05-01', 'pendente');

-- Criar relacionamento com cobrança
INSERT INTO acordoCobrancas (acordoId, cobrancaId, valorOriginal)
VALUES (@acordo_id, 1, 500000);

SELECT @acordo_id as acordoId;

